create database HospitalAndPatientPortal;
use HospitalAndPatientPortal;

CREATE TABLE IF NOT EXISTS Hospital (
    hospital_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    hospital_code VARCHAR(30) NOT NULL UNIQUE,
    hospital_name VARCHAR(150) NOT NULL,
    registration_number VARCHAR(100) UNIQUE,
    phone VARCHAR(20),
    email VARCHAR(150),
    website VARCHAR(255),
    address_line1 VARCHAR(255),
    address_line2 VARCHAR(255),
    city VARCHAR(100),
    state VARCHAR(100),
    country VARCHAR(100) DEFAULT 'India',
    pincode VARCHAR(10),
    hospital_type VARCHAR(50),
    status BOOLEAN DEFAULT TRUE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);


CREATE TABLE IF NOT EXISTS Department (
    department_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    hospital_id BIGINT UNSIGNED NOT NULL,
    department_code VARCHAR(30) NOT NULL,
    department_name VARCHAR(100) NOT NULL,
    department_type VARCHAR(100),
    floor_number INT,
    phone VARCHAR(20),
    status BOOLEAN DEFAULT TRUE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_department_hospital
        FOREIGN KEY (hospital_id)
        REFERENCES Hospital(hospital_id)
);



-- Ward table
CREATE TABLE IF NOT EXISTS Ward (
    ward_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    hospital_id BIGINT UNSIGNED NOT NULL,
    department_id BIGINT UNSIGNED NOT NULL,
    ward_code VARCHAR(30) UNIQUE NOT NULL,
    ward_name VARCHAR(100) NOT NULL,
    ward_type VARCHAR(50),
    floor_number INT,
    capacity INT,
    status BOOLEAN DEFAULT TRUE,

    FOREIGN KEY (hospital_id) REFERENCES Hospital(hospital_id),
    FOREIGN KEY (department_id) REFERENCES Department(department_id)
);


-- Room table
CREATE TABLE IF NOT EXISTS Room (
    room_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    ward_id BIGINT UNSIGNED NOT NULL,
    room_number VARCHAR(30) NOT NULL,
    room_type VARCHAR(50),
    floor_number INT,
    daily_charge DECIMAL(10,2),
    status VARCHAR(30) DEFAULT 'Available',

    FOREIGN KEY (ward_id) REFERENCES Ward(ward_id)
);


-- Bed table
CREATE TABLE IF NOT EXISTS Bed (
    bed_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    room_id BIGINT UNSIGNED NOT NULL,
    bed_number VARCHAR(30) NOT NULL,
    bed_type VARCHAR(50),
    status VARCHAR(30) DEFAULT 'Available',
    daily_charge DECIMAL(10,2),

    FOREIGN KEY (room_id) REFERENCES Room(room_id)
);

-- Doctor table
CREATE TABLE IF NOT EXISTS Doctor (
    doctor_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    hospital_id BIGINT UNSIGNED NOT NULL,
    department_id BIGINT UNSIGNED NOT NULL,
    doctor_code VARCHAR(30) UNIQUE NOT NULL,
    doctor_name VARCHAR(150) NOT NULL,
    gender VARCHAR(20),
    specialization VARCHAR(100),
    qualification VARCHAR(100),
    experience_years INT,
    phone VARCHAR(20),
    email VARCHAR(150),
    consultation_fee DECIMAL(10,2),
    joining_date DATE,
    status BOOLEAN DEFAULT TRUE,

    FOREIGN KEY (hospital_id) REFERENCES Hospital(hospital_id),
    FOREIGN KEY (department_id) REFERENCES Department(department_id)
);


-- Medicine table
CREATE TABLE IF NOT EXISTS Medicine (
    medicine_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    medicine_code VARCHAR(30) UNIQUE NOT NULL,
    medicine_name VARCHAR(150) NOT NULL,
    generic_name VARCHAR(150),
    category VARCHAR(100),
    manufacturer VARCHAR(150),
    unit_price DECIMAL(10,2),
    stock_quantity INT,
    reorder_level INT,
    expiry_date DATE,
    prescription_required BOOLEAN DEFAULT TRUE,
    status BOOLEAN DEFAULT TRUE
);



-- Patient table
CREATE TABLE IF NOT EXISTS Patient (
    patient_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    patient_code VARCHAR(30) UNIQUE NOT NULL,
    patient_name VARCHAR(150) NOT NULL,
    gender VARCHAR(20),
    date_of_birth DATE,
    blood_group VARCHAR(10),
    phone VARCHAR(20),
    email VARCHAR(150),
    address VARCHAR(255),
    city VARCHAR(100),
    state VARCHAR(100),
    emergency_contact VARCHAR(20),
    registration_date DATETIME DEFAULT CURRENT_TIMESTAMP,
    status BOOLEAN DEFAULT TRUE
);


-- Patient_Insurance table
CREATE TABLE IF NOT EXISTS Patient_Insurance (
    patient_insurance_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    patient_id BIGINT UNSIGNED NOT NULL,
    insurance_provider VARCHAR(150),
    policy_number VARCHAR(100) UNIQUE,
    policy_type VARCHAR(50),
    coverage_amount DECIMAL(12,2),
    start_date DATE,
    end_date DATE,
    status VARCHAR(30),
    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id)
);


-- User table
CREATE TABLE IF NOT EXISTS `User` (
    user_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    hospital_id BIGINT UNSIGNED NOT NULL,
    username VARCHAR(100) UNIQUE NOT NULL,
    full_name VARCHAR(150),
    email VARCHAR(150),
    phone VARCHAR(20),
    password_hash VARCHAR(255),
    status BOOLEAN DEFAULT TRUE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (hospital_id) REFERENCES Hospital(hospital_id)
);
 show tables;
 
 -- Role table
CREATE TABLE IF NOT EXISTS Role (
    role_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    role_name VARCHAR(100) UNIQUE NOT NULL,
    description VARCHAR(255),
    status BOOLEAN DEFAULT TRUE
);

-- Permission table
CREATE TABLE IF NOT EXISTS Permission (
    permission_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    permission_name VARCHAR(100) UNIQUE NOT NULL,
    module_name VARCHAR(100),
    description VARCHAR(255),
    status BOOLEAN DEFAULT TRUE
);

-- Appointment table
CREATE TABLE IF NOT EXISTS Appointment (
    appointment_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    patient_id BIGINT UNSIGNED NOT NULL,
    doctor_id BIGINT UNSIGNED NOT NULL,
    department_id BIGINT UNSIGNED NOT NULL,
    appointment_date DATE NOT NULL,
    appointment_time TIME NOT NULL,
    appointment_type VARCHAR(50),
    reason VARCHAR(255),
    status VARCHAR(30),
    consultation_fee DECIMAL(10,2),

    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id),
    FOREIGN KEY (doctor_id) REFERENCES Doctor(doctor_id),
    FOREIGN KEY (department_id) REFERENCES Department(department_id)
);


-- Encounter table
CREATE TABLE IF NOT EXISTS Encounter (
    encounter_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    appointment_id BIGINT UNSIGNED,
    patient_id BIGINT UNSIGNED NOT NULL,
    doctor_id BIGINT UNSIGNED NOT NULL,
    encounter_date DATETIME NOT NULL,
    encounter_type VARCHAR(50),
    chief_complaint VARCHAR(255),
    diagnosis_summary VARCHAR(255),
    status VARCHAR(30),

    FOREIGN KEY (appointment_id) REFERENCES Appointment(appointment_id),
    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id),
    FOREIGN KEY (doctor_id) REFERENCES Doctor(doctor_id)
);


-- Diagnosis table
CREATE TABLE IF NOT EXISTS Diagnosis (
    diagnosis_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    encounter_id BIGINT UNSIGNED NOT NULL,
    patient_id BIGINT UNSIGNED NOT NULL,
    diagnosis_code VARCHAR(30),
    diagnosis_name VARCHAR(150) NOT NULL,
    diagnosis_type VARCHAR(50),
    severity VARCHAR(30),
    diagnosis_date DATE,
    notes VARCHAR(255),

    FOREIGN KEY (encounter_id) REFERENCES Encounter(encounter_id),
    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id)
);



-- Vital table
CREATE TABLE IF NOT EXISTS Vital (
    vital_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    encounter_id BIGINT UNSIGNED NOT NULL,
    patient_id BIGINT UNSIGNED NOT NULL,
    recorded_at DATETIME,
    temperature DECIMAL(4,1),
    pulse_rate INT,
    respiratory_rate INT,
    systolic_bp INT,
    diastolic_bp INT,
    oxygen_saturation DECIMAL(5,2),
    weight_kg DECIMAL(5,2),
    height_cm DECIMAL(5,2),

    FOREIGN KEY (encounter_id) REFERENCES Encounter(encounter_id),
    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id)
);



-- Clinical_Note table
CREATE TABLE IF NOT EXISTS Clinical_Note (
    clinical_note_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    encounter_id BIGINT UNSIGNED NOT NULL,
    patient_id BIGINT UNSIGNED NOT NULL,
    doctor_id BIGINT UNSIGNED NOT NULL,
    note_date DATETIME,
    note_type VARCHAR(50),
    note_text TEXT,

    FOREIGN KEY (encounter_id) REFERENCES Encounter(encounter_id),
    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id),
    FOREIGN KEY (doctor_id) REFERENCES Doctor(doctor_id)
);




-- Prescription table
CREATE TABLE IF NOT EXISTS Prescription (
    prescription_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    encounter_id BIGINT UNSIGNED NOT NULL,
    patient_id BIGINT UNSIGNED NOT NULL,
    doctor_id BIGINT UNSIGNED NOT NULL,
    prescription_date DATE NOT NULL,
    instructions VARCHAR(255),
    status VARCHAR(30) DEFAULT 'ACTIVE',

    FOREIGN KEY (encounter_id) REFERENCES Encounter(encounter_id),
    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id),
    FOREIGN KEY (doctor_id) REFERENCES Doctor(doctor_id)
);


-- Prescription_Item table
CREATE TABLE IF NOT EXISTS Prescription_Item (
    prescription_item_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    prescription_id BIGINT UNSIGNED NOT NULL,
    medicine_id BIGINT UNSIGNED NOT NULL,
    dosage VARCHAR(100),
    frequency VARCHAR(100),
    duration_days INT,
    quantity INT,
    unit_price DECIMAL(10,2),

    FOREIGN KEY (prescription_id) REFERENCES Prescription(prescription_id),
    FOREIGN KEY (medicine_id) REFERENCES Medicine(medicine_id)
);


-- Lab_Test table
CREATE TABLE IF NOT EXISTS Lab_Test (
    lab_test_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    test_code VARCHAR(30) UNIQUE NOT NULL,
    test_name VARCHAR(150) NOT NULL,
    category VARCHAR(100),
    sample_type VARCHAR(100),
    normal_range VARCHAR(100),
    test_cost DECIMAL(10,2),
    turnaround_hours INT,
    status BOOLEAN DEFAULT TRUE
);


-- Lab_Order table
CREATE TABLE IF NOT EXISTS Lab_Order (
    lab_order_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    patient_id BIGINT UNSIGNED NOT NULL,
    encounter_id BIGINT UNSIGNED,
    doctor_id BIGINT UNSIGNED NOT NULL,
    lab_test_id BIGINT UNSIGNED NOT NULL,
    order_date DATETIME,
    priority VARCHAR(30),
    status VARCHAR(30),

    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id),
    FOREIGN KEY (encounter_id) REFERENCES Encounter(encounter_id),
    FOREIGN KEY (doctor_id) REFERENCES Doctor(doctor_id),
    FOREIGN KEY (lab_test_id) REFERENCES Lab_Test(lab_test_id)
);

-- Lab_Result table
CREATE TABLE IF NOT EXISTS Lab_Result (
    lab_result_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    lab_order_id BIGINT UNSIGNED NOT NULL,
    result_date DATETIME,
    result_value VARCHAR(255),
    unit VARCHAR(50),
    reference_range VARCHAR(100),
    result_status VARCHAR(30),
    remarks VARCHAR(255),

    FOREIGN KEY (lab_order_id) REFERENCES Lab_Order(lab_order_id)
);

-- Admission table
CREATE TABLE IF NOT EXISTS Admission (
    admission_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    patient_id BIGINT UNSIGNED NOT NULL,
    doctor_id BIGINT UNSIGNED NOT NULL,
    admission_date DATETIME NOT NULL,
    admission_type VARCHAR(50),
    reason VARCHAR(255),
    diagnosis VARCHAR(255),
    status VARCHAR(30),

    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id),
    FOREIGN KEY (doctor_id) REFERENCES Doctor(doctor_id)
);



-- Bed_Assignment table
CREATE TABLE IF NOT EXISTS Bed_Assignment (
    bed_assignment_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    admission_id BIGINT UNSIGNED NOT NULL,
    patient_id BIGINT UNSIGNED NOT NULL,
    bed_id BIGINT UNSIGNED NOT NULL,
    assigned_from DATETIME,
    assigned_to DATETIME,
    status VARCHAR(30),

    FOREIGN KEY (admission_id) REFERENCES Admission(admission_id),
    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id),
    FOREIGN KEY (bed_id) REFERENCES Bed(bed_id)
);

-- Discharge table
CREATE TABLE IF NOT EXISTS Discharge (
    discharge_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    admission_id BIGINT UNSIGNED NOT NULL,
    patient_id BIGINT UNSIGNED NOT NULL,
    discharge_date DATETIME,
    discharge_type VARCHAR(50),
    final_diagnosis VARCHAR(255),
    treatment_summary TEXT,
    follow_up_date DATE,
    doctor_id BIGINT UNSIGNED NOT NULL,

    FOREIGN KEY (admission_id) REFERENCES Admission(admission_id),
    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id),
    FOREIGN KEY (doctor_id) REFERENCES Doctor(doctor_id)
);


-- Service table
CREATE TABLE IF NOT EXISTS Service (
    service_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    service_code VARCHAR(30) UNIQUE NOT NULL,
    service_name VARCHAR(150) NOT NULL,
    category VARCHAR(100),
    description VARCHAR(255),
    service_charge DECIMAL(10,2),
    status BOOLEAN DEFAULT TRUE
);


-- Invoice table
CREATE TABLE IF NOT EXISTS Invoice (
    invoice_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    patient_id BIGINT UNSIGNED NOT NULL,
    admission_id BIGINT UNSIGNED,
    invoice_number VARCHAR(50) UNIQUE NOT NULL,
    invoice_date DATE,
    subtotal DECIMAL(12,2),
    discount DECIMAL(12,2),
    tax DECIMAL(12,2),
    total_amount DECIMAL(12,2),
    status VARCHAR(30),

    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id),
    FOREIGN KEY (admission_id) REFERENCES Admission(admission_id)
);

SELECT invoice_id, patient_id, admission_id, invoice_number
FROM Invoice
ORDER BY invoice_id;
SELECT *
FROM Invoice
WHERE invoice_number = 'INV-0000001';
DELETE FROM Invoice;
select * from invoice;

-- Invoice_Item table
CREATE TABLE IF NOT EXISTS Invoice_Item (
    invoice_item_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    invoice_id BIGINT UNSIGNED NOT NULL,
    service_id BIGINT UNSIGNED NOT NULL,
    description VARCHAR(255),
    quantity INT,
    unit_price DECIMAL(10,2),
    amount DECIMAL(12,2),

    FOREIGN KEY (invoice_id) REFERENCES Invoice(invoice_id),
    FOREIGN KEY (service_id) REFERENCES Service(service_id)
);



-- Payment table
CREATE TABLE IF NOT EXISTS Payment (
    payment_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    invoice_id BIGINT UNSIGNED NOT NULL,
    patient_id BIGINT UNSIGNED NOT NULL,
    payment_date DATE,
    payment_method VARCHAR(50),
    transaction_reference VARCHAR(100),
    amount DECIMAL(12,2),
    payment_status VARCHAR(30),

    FOREIGN KEY (invoice_id) REFERENCES Invoice(invoice_id),
    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id)
);


-- Insurance_Claim table
CREATE TABLE IF NOT EXISTS Insurance_Claim (
    claim_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    patient_id BIGINT UNSIGNED NOT NULL,
    patient_insurance_id BIGINT UNSIGNED NOT NULL,
    invoice_id BIGINT UNSIGNED NOT NULL,
    claim_number VARCHAR(50) UNIQUE NOT NULL,
    claim_date DATE,
    claimed_amount DECIMAL(12,2),
    approved_amount DECIMAL(12,2),
    claim_status VARCHAR(30),
    rejection_reason VARCHAR(255),

    FOREIGN KEY (patient_id) REFERENCES Patient(patient_id),
    FOREIGN KEY (patient_insurance_id)
        REFERENCES Patient_Insurance(patient_insurance_id),
    FOREIGN KEY (invoice_id) REFERENCES Invoice(invoice_id)
);


-- Audit_Log table
CREATE TABLE IF NOT EXISTS Audit_Log (
    audit_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    action_type VARCHAR(50),
    table_name VARCHAR(100),
    record_id BIGINT UNSIGNED,
    action_date DATETIME,
    ip_address VARCHAR(50),
    description VARCHAR(255),

    FOREIGN KEY (user_id) REFERENCES `User`(user_id)
);

 
 
 
 
